from pathlib import Path
R=Path(__file__).resolve().parents[1];L=R.parent/'Singapore Maths Paper Library';p=Path(glob.glob(str(L/'structure/*/next120-review/batch4EarlyReview.json'))[0]);review=json.loads(p.read_text());db=sqlite3.connect(L/'coverage/ledger.sqlite');db.row_factory=sqlite3.Row;patterns={};units=[];shared=['src/primary/paperImports/batch4EarlyMeta.ts','src/primary/paperImports/batch4EarlyPicture.ts','src/primary/paperImports/batch4EarlyDiagram.tsx','src/engine/random.ts','src/primary/generate.ts','src/primary/answerFormat.ts','src/primary/groupingAnswer.ts','src/primary/Picture.tsx']
